package Practice;

public class Relation {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		int a=20;
		int b=10;
		
		System.out.println(a>b);
		System.out.println(a>=b);
		System.out.println(a<b);
		System.out.println(a<=b);
		System.out.println(a==b);
		System.out.println(a!=b);
		
		// >,>=,<,<=,==,!= are  relational operators 
		// it returns boolean values true or false
		
	}

}
